import { useEffect, useState, type ReactNode } from "react";
import { ensureSignedIn } from "@/auth/oauth";
import { useAppStore } from "@/store/useAppStore";

interface AuthGateProps {
  children: ReactNode;
}

/**
 * Блокує рендер дочірнього UI, доки OAuth2-логін проти Portal не завершиться.
 * При помилці показує інформаційний notice з поясненням (зазвичай — невідповідність redirect URI).
 */
export function AuthGate({ children }: AuthGateProps) {
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading");
  const [error, setError] = useState<string | null>(null);
  const setCredential = useAppStore((s) => s.setCredential);

  useEffect(() => {
    let cancelled = false;

    ensureSignedIn()
      .then((credential) => {
        if (cancelled) return;
        setCredential(credential);
        setStatus("ready");
      })
      .catch((err) => {
        if (cancelled) return;
        console.error("Auth failed", err);

        let errorMessage = "Помилка автентифікації";
        if (err?.message?.includes("invalid_grant")) {
          errorMessage =
            "Невірні дані для входу. Перевірте облікові дані на Portal.";
        } else if (err?.message?.includes("redirect_uri")) {
          errorMessage =
            "Помилка redirect URI. Переконайтеся, що адреса в Application item на Portal " +
            "збігається з поточною URL (включно з наявністю trailing slash).";
        } else if (err?.message) {
          errorMessage = err.message;
        }

        setError(errorMessage);
        setStatus("error");
      });

    return () => {
      cancelled = true;
    };
  }, [setCredential]);

  if (status === "loading") {
    return <calcite-loader label="Автентифікація..." scale="l" />;
  }

  if (status === "error") {
    return (
      <div style={{ padding: "20px" }}>
        <calcite-notice open kind="danger" icon="exclamation-mark-triangle">
          <div slot="title">Не вдалося увійти</div>
          <div slot="message">{error}</div>
        </calcite-notice>
        <div style={{ marginTop: "16px", fontSize: "14px", color: "var(--calcite-color-text-2)" }}>
          <p>
            Якщо проблема не розв'язується, звернітеся до адміністратора Portal або перевірте:
          </p>
          <ul>
            <li>Чи зареєстрований цей URL як Redirect URI в Application item</li>
            <li>Чи совпадает схема (http/https) і наявність trailing slash</li>
            <li>Чи доступна сторінка логіну Portal</li>
          </ul>
        </div>
      </div>
    );
  }

  return <>{children}</>;
}
